# Temporary exact-source patch transport. Removed by the verification workflow.
# The payload contains only public Web source edits, tests and their before/after
# SHA-256 values. All inputs and outputs are checked before any file is written.
import base64
import hashlib
import json
import lzma
from pathlib import Path

PAYLOAD = ''''''
raw = lzma.decompress(base64.b64decode(PAYLOAD))
assert hashlib.sha256(raw).hexdigest() == '7ee76411d21c9a3681cbac0cb1509676f7ca76bfcffd21325a1dece4b922a15f', 'payload checksum mismatch'
changes = json.loads(raw)
assert len(changes) == 12
planned = []
for name, item in changes.items():
    path = Path(name)
    assert not path.is_absolute() and '..' not in path.parts and '.git' not in path.parts
    if item['before'] is None:
        assert not path.exists(), f'new path already exists: {name}'
        old = b''
    else:
        old = path.read_bytes()
        assert hashlib.sha256(old).hexdigest() == item['before'], f'source drift: {name}'
    lines = old.decode('utf-8').splitlines(keepends=True)
    for start, end, replacement in reversed(item['edits']):
        lines[start:end] = replacement.splitlines(keepends=True)
    content = ''.join(lines).encode('utf-8')
    assert hashlib.sha256(content).hexdigest() == item['after'], f'candidate mismatch: {name}'
    planned.append((path, content))
for path, content in planned:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(content)
    print(path, hashlib.sha256(content).hexdigest())
